class Storage:
    def __init__(self):
        self.users: Dict[str, User] = {}
        self.stories: Dict[str, Story] = {}
        self.versions: Dict[str, List[Version]] = defaultdict(list)  # story_id -> [Version]
        self.comments: Dict[str, List[Comment]] = defaultdict(list)  # story_id -> [Comment]
        self.notifications: Dict[str, List[Notification]] = defaultdict(list)  # user_id -> [Notification]
        self.invitations: Dict[str, Dict] = {}  # invitation_id -> {story_id, inviter_id, invitee_email, status, created_at}
        self._lock = threading.RLock()

    def get_user(self, user_id: str) -> Optional[User]:
        with self._lock:
            return self.users.get(user_id)

    def get_story(self, story_id: str) -> Optional[Story]:
        with self._lock:
            return self.stories.get(story_id)

    def get_versions(self, story_id: str) -> List[Version]:
        with self._lock:
            return sorted(self.versions.get(story_id, []), key=lambda v: v.timestamp)

    def get_comments(self, story_id: str) -> List[Comment]:
        with self._lock:
            return sorted(self.comments.get(story_id, []), key=lambda c: c.created_at)

    def get_notifications(self, user_id: str) -> List[Notification]:
        with self._lock:
            return sorted(self.notifications.get(user_id, []), key=lambda n: n.created_at, reverse=True)


